dates=D['SPX'].index[(D['SPX'].index>='2020-04-01')&(D['SPX'].index<=end)]
C=pd.DataFrame({s:D[s].close.reindex(dates) for s in U}); r=C.pct_change()
# Market-residual medium-term momentum: asset 30d return minus trailing 60d beta to equal-weight tradable benchmark * benchmark 30d return.
M=r.mean(axis=1); mr=M.rolling(60,min_periods=45).mean(); vr=M.rolling(60,min_periods=45).var()
beta=pd.DataFrame({s:r[s].rolling(60,min_periods=45).cov(M)/(vr+1e-8) for s in U})
R30=C.pct_change(30); m30=(1+M).rolling(30,min_periods=25).apply(np.prod,raw=True)-1
F=(R30-beta*m30).rank(axis=1,pct=True).shift(1)

def met(x):
